import{_ as o,o as a,c as e,a2 as r}from"./chunks/framework.DnrXFDHb.js";const l=JSON.parse('{"title":"电比芯片更稀缺：算电协同真正的瓶颈不是电","description":"","frontmatter":{"title":"电比芯片更稀缺：算电协同真正的瓶颈不是电","updated":"2026-08-19T00:00:00.000Z","visibility":"public"},"headers":[],"relativePath":"算电协同/电比芯片更稀缺_算电协同真正的瓶颈不是电.md","filePath":"算电协同/电比芯片更稀缺_算电协同真正的瓶颈不是电.md","lastUpdated":1789119850000}'),d={name:"算电协同/电比芯片更稀缺_算电协同真正的瓶颈不是电.md"};function u(p,t,q,h,n,i){return a(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="电比芯片更稀缺-算电协同真正的瓶颈-不是电" tabindex="-1">电比芯片更稀缺？算电协同真正的瓶颈，不是电 <a class="header-anchor" href="#电比芯片更稀缺-算电协同真正的瓶颈-不是电" aria-label="Permalink to &quot;电比芯片更稀缺？算电协同真正的瓶颈，不是电&quot;">​</a></h1><h2 id="副题-中国不缺电——缺的是对的时间、对的地点、对的颜色的电-三重错配-才是算电协同要解的那道题" tabindex="-1">副题：中国不缺电——缺的是对的时间、对的地点、对的颜色的电；三重错配，才是算电协同要解的那道题 <a class="header-anchor" href="#副题-中国不缺电——缺的是对的时间、对的地点、对的颜色的电-三重错配-才是算电协同要解的那道题" aria-label="Permalink to &quot;副题：中国不缺电——缺的是对的时间、对的地点、对的颜色的电；三重错配，才是算电协同要解的那道题&quot;">​</a></h2><p>2025 年 9 月，微软和星座能源签了一份为期 20 年的购电协议，只为重启一座 2019 年就关停的核电站——三里岛。Meta 紧随其后签了 20 年核能采购，亚马逊砸 200 亿美元在宾州建直连核电站的数据中心园区。亚马逊 CEO 贾西对投资者说得坦白：&quot;最大的限制因素是电力。&quot;[1]在大西洋对岸，这已经不是叙事，是现金流。</p><p>同一年的中国，国家能源局公布了另一组数字：2025 年全社会用电量 103682 亿千瓦时，历史上首次突破 10 万亿度，相当于美国全年用电量的两倍多；全国算力中心总用电量 1700 亿度，占全社会用电量的 1.6%[2][3]。</p><p>一边是大厂为电抢核电站，一边是用电全球第一、算力用电占比不到两个点。这篇文章要回答的问题就藏在这组反差里：电到底是不是 AI 的瓶颈？先把结论亮出来。**电从来不是绝对稀缺，稀缺的是三重错配——对的时间、对的地点、对的颜色的电。中美面对的是同一道题的两种错法：美国错在交付，中国错在结构。**看错了瓶颈，后面的投资动作会全错。</p><h2 id="电荒-叙事是怎么炼成的" tabindex="-1">&quot;电荒&quot;叙事是怎么炼成的 <a class="header-anchor" href="#电荒-叙事是怎么炼成的" aria-label="Permalink to &quot;&quot;电荒&quot;叙事是怎么炼成的&quot;">​</a></h2><p>先说美国，那里的电荒是真的，但荒的不是发电量，是交付。TrendForce 的调研显示，美国多数电网区域的发电容量其实够，瓶颈卡在输电环节——PJM 区域新规划的数据中心，并网等待可能超过五年；大型电力变压器的平均交期已拉长到两年半，345 千伏以上高电压等级要四到五年，比 2020 年翻了一倍[4]。排队的不只是数据中心，整个并网队列里躺着 2600 吉瓦的发电和储能项目，比美国现有全部装机还多。微软们签核电、买燃气轮机、自建电源，不是电买不起，是队排不起。</p><p>中国的问题完全不是这个。论总量，2025 年可再生能源发电 3.99 万亿度，占总发电量 38.3%，全年新增用电增量第一次全部由绿电覆盖[3]。论算力占比，1.6% 的盘子，就算按券商测算到 2030 年涨到 7000 亿度、占比 5% 以上，也谈不上&quot;电不够&quot;[3][5]。</p><p>中国的约束在另外三个地方。增长速度错配：算力用电近三年平均增速约 39.5%，是全社会用电增速的近八倍，电网规划按五年编，算力需求按季度翻[3]。空间错配：绿电在西北，负荷在东南，训练可以西迁，推理必须东沉——这是本系列选址篇拆过的账，此处不展开。指标错配：枢纽节点新建数据中心绿电占比要超 80%，这不是成本问题，是准入问题，拿不到绿电凭证，项目连出生证都领不到[6]。三重错配叠在一起，就是&quot;算电协同&quot;这四个字 2026 年 3 月 5 日写进政府工作报告的全部背景[6]。</p><h2 id="拆一个流行的误判-电比芯片更稀缺" tabindex="-1">拆一个流行的误判：&quot;电比芯片更稀缺&quot; <a class="header-anchor" href="#拆一个流行的误判-电比芯片更稀缺" aria-label="Permalink to &quot;拆一个流行的误判：&quot;电比芯片更稀缺&quot;&quot;">​</a></h2><p>这句话传播极广，还总带着 IEA 的数据撑腰——数据中心耗电五年翻倍，2030 年到 950TWh，接近日本全国用电量[7]。数据是真的，结论是歪的，歪在三个地方。</p><p>第一处，它混淆了两种稀缺的性质。芯片的稀缺是&quot;有没有&quot;：先进制程产能集中在台积电一家，高端 GPU 被出口管制卡着，掏钱也买不到，对策只能是囤货和国产替代。电力的瓶颈是&quot;快不快、绿不绿、在哪里&quot;：电是可再生的，中国装机全球第一，没有买不到，只有等不及、不匹配。<strong>前者是存量争夺，后者是排队优化，把两种问题混成一句口号，对策必然开错药方。</strong></p><p>第二处，它误导了投资动作。信了&quot;电荒&quot;的人，会去赌电价上涨。但中国的工商业电价有政策约束，中卫绿电直供的到户价稳定在 0.36 元一度上下，比东部便宜一半还多[8]。电价没有暴涨的逻辑——真涨价的不是电，是并网容量、绿电凭证、调度优先级这些准入型资产。<strong>电荒叙事最大的受害者，就是把筹码押在电价上的人：真正升值的从来不是电价，是准入。</strong></p><p>第三处，它低估了制度变量。美国的瓶颈是市场碎片化的结果，电网私有、审批分散，只能靠巨头逐点突围。中国 2026 年已经把算电协同列为国家任务，&quot;8+10+3&quot;的算力空间布局落纸，国家级监测调度平台接入 137 万 P 智能算力、占全国总量 72%[6][9]。并网、绿电、调度三件事在同一张图上协调，这是美国体制给不出的解法。用美国的瓶颈套用中国的判断，是拿错了地图。</p><h2 id="往深看一层-数据中心正在从电网的负担-变成电网的资源" tabindex="-1">往深看一层：数据中心正在从电网的负担，变成电网的资源 <a class="header-anchor" href="#往深看一层-数据中心正在从电网的负担-变成电网的资源" aria-label="Permalink to &quot;往深看一层：数据中心正在从电网的负担，变成电网的资源&quot;">​</a></h2><p>把三重错配拆开之后，真正的趋势才浮出水面：算电协同的终局，不是&quot;算力找电&quot;，而是算电互调。</p><p>传统关系里，数据中心是电网最头疼的负荷——功率大、波动猛、24 小时不停。但换一个视角，它恰恰是新型电力系统最缺的东西：体量大、可中断、可调度的柔性负荷。训练任务可以跟着电价和绿电出力挪时间，推理可以跟着用户挪空间，储能和柴发平时待命、关键时刻反向支撑电网。国家数据局局长刘烈宏把这叫&quot;以电强算、以算促电&quot;——电支撑算，算反哺电[6]。中卫的双轨模式已经跑通：光伏电站物理直供加双边交易，数据中心既是消纳绿电的出口，又是电网的调节资源[8]。</p><p>有人会质疑：绿电 80% 的硬指标，会不会反而压垮项目经济性？这个担心在东部成立，在枢纽节点内恰好相反。绿电直供把电费压到 0.36 元，电力成本占数据中心运营成本的六成以上，这一压就是利润表上最粗的一条线[8][9]。约束和红利是同一枚硬币的两面，区别只在于你的项目站没站对位置。</p><p>把这张地图存下来，比看十篇行业综述管用：</p><table tabindex="0"><thead><tr><th>错配</th><th>病灶</th><th>美国解法</th><th>中国解法</th><th>该锁定的资产</th></tr></thead><tbody><tr><td>时间</td><td>并网排队、设备交期</td><td>自带电源、抢变压器</td><td>枢纽统一规划、集中交付</td><td>并网容量</td></tr><tr><td>空间</td><td>电源与负荷错位</td><td>算力迁往德州等富电区</td><td>东数西算、训练西迁推理东沉</td><td>枢纽节点指标</td></tr><tr><td>颜色</td><td>绿电指标 vs 消纳能力</td><td>企业 PPA、绿证采购</td><td>绿电直供+监测调度</td><td>绿电长协与凭证</td></tr></tbody></table><h2 id="我的判断-看多协同-反对赌电价" tabindex="-1">我的判断：看多协同，反对赌电价 <a class="header-anchor" href="#我的判断-看多协同-反对赌电价" aria-label="Permalink to &quot;我的判断：看多协同，反对赌电价&quot;">​</a></h2><p>立场说清楚：算电协同作为十年级的主线，我明确看多；&quot;电算一体&quot;的跨资产组合——把电源、并网、机柜、调度、交易打包，卖&quot;可用算力+可证明绿电&quot;——是未来三五年最强的盈利模型，这个判断我和市场共识一致。但对一类交易策略明确反对：把算电协同理解成&quot;电价要涨&quot;，去囤电力资产赌涨价，方向就反了。中国的政策目标恰恰是用协同把算力的用电成本压下来，而不是抬上去。</p><p>理由三条。政策确定性：算电协同进了政府工作报告，全国一体化算力网进了&quot;十五五&quot;109 项重大工程，四大方向由国家数据局公开背书，这是少有的顶层、执行、考核三层全部对齐的赛道[6]。比较优势：中国的核心竞争力是交付速度——美国并网排八年，中国枢纽节点集中交付，这个优势只要保持住，全球算力产能的地理分布就会继续向中国倾斜[4][6]。需求真实性：39.5% 的算力用电增速不是预测，是能源局口径的三年实测[3]。</p><p>窗口期判断：2026 到 2028 年是锁资源的窗口，并网容量、绿电长协、调度平台接入三件事，先到先得、后到排队；2028 年之后，随着供给扩容和定价机制成熟，准入型资产的稀缺溢价会逐步被摊薄，届时拼的是运营，不是卡位。</p><h2 id="三类读者-各取所需" tabindex="-1">三类读者，各取所需 <a class="header-anchor" href="#三类读者-各取所需" aria-label="Permalink to &quot;三类读者，各取所需&quot;">​</a></h2><p>对政策制定者，最该守住的是交付速度这个比较优势。建议把并网时效纳入枢纽节点的考核指标，公开排队时长，别让美国的&quot;八年排队&quot;在中国重演；绿电核算逐步从年度电量匹配走向更精细的时段匹配，让&quot;可证明的绿电&quot;真正可交易；需求响应和辅助服务市场该向数据中心正式开门了，补偿标准定清楚，137 万 P 的监测接入量就是现成的调节资源池[6]。</p><p>对企业决策者，尽调时立四本台账：电力资源台账记并网容量和电价结构，算力负荷台账记真实负载曲线，碳与绿电台账记凭证来源和缺口，现金流台账记电费和绿电溢价的传导路径。四本账对不上，项目故事讲得再好也不要投。资源配置上，把并网容量和绿电长协排在土地前面锁定——地永远有，准入没有。</p><p>对高层执行者，两件具体事。报装容量和实际负载的偏差管住，负荷预测做得准，并网审批才走得快，这是交付速度在微观层面的对应动作；监测调度平台尽早接入，全国 72% 的智能算力已经在册，不接入就是游离于调度体系外的黑户，未来的绿电配额、需求响应补偿，都会优先给在册的[6]。</p><p>最后留一个问题：今天所有人都在问&quot;电够不够&quot;，可等并网容量、绿电凭证、调度优先级都成了标配，算电协同竞争的下一道题，会不会变成——谁的算力，最会替电网打工？</p><hr><p><strong>数据来源</strong></p><p>[1] 微信公众号（AI产业观察），《AI浪潮下的电力危机：美国数据中心扩张遭遇电网天花板》，2025-08-21 [2] 新华网，《全球首次，2025年我国全社会用电量超10万亿千瓦时》，2026-01-19 [3] 新浪财经，《上半年煤电发电量占比首次低于50%，&quot;十五五&quot;加快推进绿电支撑新增用电量》，2026-08-14 [4] 与非网（TrendForce集邦咨询研报），《英伟达800V Power Rack成Vera Rubin选用方案》，2026-06-26 [5] 雪球（券商研报转载），《算力需求快速增长驱动用电量增长》，2026-05-19 [6] 国家数据局官网，《国家数据局明确算力基建四大方向》，2026-04-30 [7] 36氪（红杉汇梳理IEA报告），《IEA报告：未来五年数据中心电耗将翻倍，谁来为AI供电？》，2026-05-10 [8] 国家能源局，《全国首个大规模&quot;算电协同&quot;绿电直供项目投运》，2026-05-08；新浪财经（预见能源），《里程碑！全国首个大规模算电协同项目并网》，2026-05-03 [9] 东方财富网，《&quot;六张网&quot;新机遇·上市公司在行动｜算力网如何织就数智经济新底座》，2026-08-10</p><p><strong>风险提示</strong></p><p>本文判断存在三层不确定性：一是需求兑现节奏，39.5% 的算力用电增速是过去三年实测，若 AI 应用商业化放缓或推理能效超预期提升，增速曲线可能提前见顶，锁定过量电力资源的项目将承担闲置成本；二是政策执行尺度，绿电 80%、监测调度接入等要求的核查方式仍在细化，时段级绿电核算若推进过快，存量项目的绿电缺口会提前暴露；三是国际对标变量，美国若通过审批改革显著缩短并网周期，中国交付速度的比较优势会被动收窄。文中中美数据分属不同统计口径，横向对比仅供方向参考，项目决策请以电网公司和能评批复的正式文件为准。</p><p>关注本号，持续追踪&quot;算电协同&quot;赛道的政策、产业与资本信号。</p>',35)])])}const s=o(d,[["render",u]]);export{l as __pageData,s as default};
